import unittest
from settings import effective_limit

class TestEffectiveLimit(unittest.TestCase):

    def test_none_uses_default(self):
        # None means default (default=10 is used in the implementation)
        self.assertEqual(effective_limit(None), 10)

    def test_zero_stays_zero(self):
        # Zero means disabled and must stay zero
        self.assertEqual(effective_limit(0), 0)

    def test_positive_int_overrides_default(self):
        # Positive int overrides default (default=10)
        self.assertEqual(effective_limit(5), 5)
        self.assertEqual(effective_limit(100), 100)

    def test_negative_int_raises_value_error(self):
        # Negative int raises ValueError
        with self.assertRaises(ValueError):
            effective_limit(-1)
        with self.assertRaises(ValueError):
            effective_limit(-100)

    def test_positive_int_with_different_default(self):
        # Test overriding default when provided
        self.assertEqual(effective_limit(5, default=50), 5)

    def test_none_with_different_default(self):
        # Test None with different default
        self.assertEqual(effective_limit(None, default=50), 50)

    def test_zero_with_different_default(self):
        # Test zero with different default
        self.assertEqual(effective_limit(0, default=50), 0)

if __name__ == '__main__':
    unittest.main()
